{
    DateTime endDate;

    switch (unit)
    {
        case "h":
            endDate = startDate.AddBusinessHours(Convert.ToInt32(deadline), offsetTimezone);
            break;
        case "d":
            endDate = startDate.AddBusinessDays(Convert.ToInt32(deadline));
            break;
        case "w":
            endDate = startDate + TimeSpan.FromDays(deadline * 7);
            break;
        default:
            throw new ArgumentException("Invalid unit: " + unit, nameof(unit));

    }

    return endDate;
}
